1	//! The set version: the agent-files' own version, read from the
2	//! workspace the command runs in.
3	//!
4	//! The set's version-of-record is an empty file,
5	//! `agent-data/agent-files-vX.Y.Z{-suffix}`, whose name is the
6	//! version (versioning.md's The set's version). It is the workspace's
7	//! set that is reported, never the set this binary's own repo carried
8	//! when it was built.
9	//!
10	//! - `versions(root)`: the `v...` names under `<root>/agent-data`,
11	//!   sorted, empty when the directory or the file is missing.
12	//! - `banner_suffix(root)`: ` (agent-files v0.1.0)` for the run
13	//!   banner, empty when there is nothing to say.
14	//! - `report_line(root)`: the `agent-files ...` line of `vc-x1
15	//!   version`, `none` with the reason when there is no version.
16	//! - `AgentFilesArgs`: the `agent-files` subcommand group, `version`
17	//!   printing the bare names one per line, for scripts, `diff`
18	//!   ([`diff`]) naming what differs from a copy of the set, `copy`
19	//!   ([`copy`]) making this set that copy, and `size` ([`size`])
20	//!   counting the set's lines and sliding the table that records
21	//!   them.
22	//! - `WorkspaceAgentFiles` / `config_at(root)`: the work side's
23	//!   `[agent-files.diff]` and `[agent-files.copy]` tables, the
24	//!   per-workspace defaults for the `diff` and `copy` operands and
25	//!   their `--custom` choice.
26	
27	use std::path::Path;
28	use std::process::ExitCode;
29	
30	use clap::{Args, Subcommand};
31	use log::error;
32	
33	use crate::common;
34	
35	pub mod copy;
36	pub mod diff;
37	pub mod size;
38	
39	/// The file-name prefix every set version file carries.
40	const PREFIX: &str = "agent-files-";
41	
42	/// The set versions recorded under `<work_root>/agent-data`, sorted.
43	///
44	/// One entry is the normal state. Several means a bump left both
45	/// names behind, which the listing shows rather than hides.
46	pub fn versions(work_root: &Path) -> Vec<String> {
47	    let Ok(entries) = std::fs::read_dir(work_root.join("agent-data")) else {
48	        return Vec::new();
49	    };
50	    let mut out: Vec<String> = entries
51	        .flatten()
52	        .filter_map(|e| e.file_name().to_str().map(str::to_owned))
53	        .filter_map(|name| name.strip_prefix(PREFIX).map(str::to_owned))
54	        .filter(|v| v.starts_with('v'))
55	        .collect();
56	    out.sort();
57	    out
58	}
59	
60	/// The banner's tail: ` (agent-files v0.1.0)`, or empty outside a
61	/// workspace and when the workspace has no version file.
62	pub fn banner_suffix(work_root: Option<&Path>) -> String {
63	    match work_root.map(versions) {
64	        Some(vs) if !vs.is_empty() => format!(" (agent-files {})", vs.join(", ")),
65	        _ => String::new(),
66	    }
67	}
68	
69	/// The `vc-x1 version` line for the set, a `none` with its reason
70	/// when there is nothing to report.
71	pub fn report_line(work_root: Option<&Path>) -> String {
72	    match work_root {
73	        None => "agent-files none: not in a vc-x1 workspace".to_string(),
74	        Some(root) => {
75	            let vs = versions(root);
76	            if vs.is_empty() {
77	                format!("agent-files none: no agent-data/{PREFIX}v* file")
78	            } else {
79	                format!("agent-files {}", vs.join(", "))
80	            }
81	        }
82	    }
83	}
84	
85	/// One command's table, `[agent-files.diff]` or
86	/// `[agent-files.copy]`: the default `DIR` operand and the
87	/// default `--custom` choice, each `None` when the key is absent.
88	#[derive(Debug, Default, PartialEq, Eq)]
89	pub struct CommandDefaults {
90	    /// `dir`: a directory holding a copy of the set, as written,
91	    /// relative to the config file's directory.
92	    pub dir: Option<String>,
93	    /// `custom`: compare or copy custom.md with the rest.
94	    pub custom: Option<bool>,
95	}
96	
97	/// The work side's `[agent-files.*]` tables.
98	#[derive(Debug, Default, PartialEq, Eq)]
99	pub struct WorkspaceAgentFiles {
100	    pub diff: CommandDefaults,
101	    pub copy: CommandDefaults,
102	}
103	
104	/// Read the `[agent-files.diff]` and `[agent-files.copy]` tables
105	/// of the config at `root`. No config, or no tables, is the
106	/// default; a `custom` that is not a bare `true` or `false` is an
107	/// error naming the key, since a malformed config is fatal rather
108	/// than silently ignored.
109	pub fn config_at(root: &Path) -> Result<WorkspaceAgentFiles, Box<dyn std::error::Error>> {
110	    let Some(cfg) = crate::config_md::load(root)? else {
111	        return Ok(WorkspaceAgentFiles::default());
112	    };
113	    let get = |key: &str| crate::toml_simple::toml_get(&cfg.map, key);
114	    let parse_bool = |key: &str| -> Result<Option<bool>, Box<dyn std::error::Error>> {
115	        match get(key).map(String::as_str) {
116	            None => Ok(None),
117	            Some("true") => Ok(Some(true)),
118	            Some("false") => Ok(Some(false)),
119	            Some(other) => Err(format!(
120	                "{key}: invalid bool {other:?}: expected true or false, unquoted"
121	            )
122	            .into()),
123	        }
124	    };
125	    Ok(WorkspaceAgentFiles {
126	        diff: CommandDefaults {
127	            dir: get("agent-files.diff.dir").cloned(),
128	            custom: parse_bool("agent-files.diff.custom")?,
129	        },
130	        copy: CommandDefaults {
131	            dir: get("agent-files.copy.dir").cloned(),
132	            custom: parse_bool("agent-files.copy.custom")?,
133	        },
134	    })
135	}
