14	/// One step of an init run.
15	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
16	pub(crate) enum Step {
17	    Colocate,
18	    PrepareWork,
19	    ConfigWork,
20	    CommitWork,
21	    PrepareAgent,
22	    ConfigAgent,
23	    CommitAgent,
24	    CrossLink,
25	    PublishAgent,
26	    ReplaceOrigin,
27	    PublishWork,
28	    Symlink,
29	}
30	
31	/// A plan's steps, each with its title.
32	pub(crate) struct Steps {
33	    list: Vec<(Step, String)>,
34	}
35	
36	impl Steps {
37	    /// The steps `plan` runs, titled with what each will do to what.
38	    pub(crate) fn new(
39	        plan: &InitPlan,
40	        params: &InitParams,
41	        visibility: &str,
42	        create_symlink: bool,
43	    ) -> Self {
44	        let mut list = Vec::new();
45	
46	        let work_dir = plan.project_dir.display();
47	        if matches!(plan.work_start, WorkStart::Repo { .. })
48	            && super::adopt::is_git_only(&plan.project_dir)
49	        {
50	            list.push((
51	                Step::Colocate,
52	                format!("Colocate the git repo {work_dir} with jj, its history kept"),
53	            ));
54	        }
55	        let prepare_work = if params.adopt {
56	            format!("Init the work repo (jj, colocated) in {work_dir}, adopting its content")
57	        } else {
58	            format!("Create {work_dir} and init the work repo (jj, colocated)")
59	        };
60	        // An adopted repo is prepared already.
61	        if plan.work_start == WorkStart::Fresh {
62	            list.push((Step::PrepareWork, prepare_work));
63	        }
64	        let config_work = match (&plan.agent, &params.config) {
65	            (Some(_), _)
66	                if matches!(
67	                    plan.work_start,
68	                    WorkStart::Repo {
69	                        has_config: true,
70	                        ..
71	                    }
72	                ) =>
73	            {
74	                "Add the agent repo to the work repo's config, in place, and to its .gitignore"
75	                    .into()
76	            }
77	            (Some(_), _) | (None, None) => {
78	                "Write the work repo's .vc-config.md and .gitignore".into()
79	            }
80	            (None, Some(ConfigKind::None)) => {
81	                "Write the work repo's .gitignore (no .vc-config.md, per --config none)".into()
82	            }
83	            (None, Some(ConfigKind::Path(p))) => format!(
84	                "Copy {} as the work repo's config and write its .gitignore",
85	                p.display()
86	            ),
87	        };
88	        let config_work = format!("{config_work}, then TODO.md and zTOC.md where absent");
89	        list.push((Step::ConfigWork, config_work));
90	        let commit_work = match plan.work_start {
91	            WorkStart::Fresh => "Commit the work repo's initial commit".to_string(),
92	            WorkStart::Repo { .. } => format!(
93	                "Commit \"{}\" on top of the work repo's history",
94	                super::ADOPT_TITLE
95	            ),
96	        };
97	        list.push((Step::CommitWork, commit_work));
98	
99	        if let Some(agent) = &plan.agent {
100	            let prepare_agent = format!(
101	                "Create {} and init the agent repo (jj, colocated)",
102	                agent.path.display()
103	            );
104	            list.push((Step::PrepareAgent, prepare_agent));
105	            list.push((
106	                Step::ConfigAgent,
107	                "Write the agent repo's .vc-config.md and .gitignore".into(),
108	            ));
109	            list.push((
110	                Step::CommitAgent,
111	                "Commit the agent repo's initial commit".into(),
112	            ));
113	            let work_commit = match plan.work_start {
114	                WorkStart::Fresh => "the work repo's initial commit",
115	                WorkStart::Repo { .. } => "the work repo's adopt commit",
116	            };
117	            list.push((
118	                Step::CrossLink,
119	                format!("Cross-link {work_commit} and the agent repo's initial commit with ochid trailers"),
120	            ));
121	            list.push((
122	                Step::PublishAgent,
123	                publish_title(plan, "agent", Some(agent), visibility),
124	            ));
125	        }
126	        // An adopted repo with an origin publishes nothing: its commit
127	        // is the user's to land.
128	        if !plan.work_start.keeps_its_origin() {
129	            if let Some(origin) = &plan.replaced_origin {
130	                let what = match &params.upstream {
131	                    Some(name) => format!("keep it as the remote '{name}'"),
132	                    None => "remove it".to_string(),
133	                };
134	                list.push((
135	                    Step::ReplaceOrigin,
136	                    format!("Replace the work repo's origin {origin} with REMOTES: {what}"),
137	                ));
138	            }
139	            list.push((
140	                Step::PublishWork,
141	                publish_title(plan, "work", None, visibility),
142	            ));
143	        }
144	        if plan.agent.is_some() && create_symlink {
145	            list.push((Step::Symlink, "Create the Claude Code symlink".into()));
146	        }
147	        Self { list }
148	    }
149	
150	    /// Print the whole list, for the dry run.
151	    pub(crate) fn print_all(&self) {
152	        for (i, (_, title)) in self.list.iter().enumerate() {
153	            info!("  {}. {title}", i + 1);
154	        }
155	    }
156	
157	    /// Announce `step` as it starts, numbered by its place in the
158	    /// list. A step the list lacks is a bug in the caller, logged
159	    /// unnumbered rather than failing the run it narrates.
160	    pub(crate) fn begin(&self, step: Step) {
